// mapper.cpp
// Find a module's base address in a running process, parse its PE export table,
// and resolve a list of symbol offsets at runtime.
// C++17, Win32 user-mode only.

#include <windows.h>
#include <tlhelp32.h>
#include <stdexcept>
#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>
#include <cstdint>
#include <cstring>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct SymbolOffset {
    std::string name;
    std::uint32_t offset; // RVA from module base
};

// ---------------------------------------------------------------------------
// FindModuleBase
// Returns the load address of `moduleName` (case-insensitive) in `pid`.
// Returns 0 if not found.
// ---------------------------------------------------------------------------
static std::uintptr_t FindModuleBase(DWORD pid, std::string_view moduleName)
{
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE)
        return 0;

    MODULEENTRY32 me{};
    me.dwSize = sizeof(me);

    std::uintptr_t base = 0;
    if (Module32First(snap, &me)) {
        do {
            // Case-insensitive comparison via CompareStringA
            int cmp = CompareStringA(
                LOCALE_INVARIANT, NORM_IGNORECASE,
                me.szModule, -1,
                moduleName.data(), static_cast<int>(moduleName.size()));
            if (cmp == CSTR_EQUAL) {
                base = reinterpret_cast<std::uintptr_t>(me.modBaseAddr);
                break;
            }
        } while (Module32Next(snap, &me));
    }

    CloseHandle(snap);
    return base;
}

// ---------------------------------------------------------------------------
// ReadRemote
// Reads `size` bytes from `address` in `process` into `buf`.
// Throws std::runtime_error on failure.
// ---------------------------------------------------------------------------
static void ReadRemote(HANDLE process, std::uintptr_t address,
                       void* buf, std::size_t size)
{
    SIZE_T read = 0;
    if (!ReadProcessMemory(process,
                           reinterpret_cast<LPCVOID>(address),
                           buf, size, &read)
        || read != size)
    {
        throw std::runtime_error(
            "ReadProcessMemory failed at 0x" +
            [address]() {
                char tmp[32];
                (void)wsprintfA(tmp, "%p", reinterpret_cast<void*>(address));
                return std::string(tmp);
            }());
    }
}

// ---------------------------------------------------------------------------
// ParseExportTable
// Reads the PE export table of a remote module and returns a map of
// exported name -> RVA.
// ---------------------------------------------------------------------------
static std::unordered_map<std::string, std::uint32_t>
ParseExportTable(HANDLE process, std::uintptr_t base)
{
    std::unordered_map<std::string, std::uint32_t> exports;

    // Read DOS header
    IMAGE_DOS_HEADER dos{};
    ReadRemote(process, base, &dos, sizeof(dos));
    if (dos.e_magic != IMAGE_DOS_SIGNATURE)
        throw std::runtime_error("Invalid DOS signature");

    // Peek at the NT signature to decide 32/64-bit
    DWORD ntSig = 0;
    ReadRemote(process, base + static_cast<std::uintptr_t>(dos.e_lfanew),
               &ntSig, sizeof(ntSig));
    if (ntSig != IMAGE_NT_SIGNATURE)
        throw std::runtime_error("Invalid NT signature");

    // Read the FileHeader to get the optional-header magic
    IMAGE_FILE_HEADER fileHdr{};
    ReadRemote(process,
               base + static_cast<std::uintptr_t>(dos.e_lfanew) + sizeof(DWORD),
               &fileHdr, sizeof(fileHdr));

    WORD optMagic = 0;
    std::uintptr_t optHdrAddr =
        base + static_cast<std::uintptr_t>(dos.e_lfanew) +
        sizeof(DWORD) + sizeof(IMAGE_FILE_HEADER);
    ReadRemote(process, optHdrAddr, &optMagic, sizeof(optMagic));

    // Export directory RVA/size
    std::uint32_t expDirRva = 0;
    std::uint32_t expDirSize = 0;

    if (optMagic == IMAGE_NT_OPTIONAL_HDR64_MAGIC) {
        IMAGE_OPTIONAL_HEADER64 opt{};
        ReadRemote(process, optHdrAddr, &opt, sizeof(opt));
        expDirRva  = opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
        expDirSize = opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].Size;
    } else if (optMagic == IMAGE_NT_OPTIONAL_HDR32_MAGIC) {
        IMAGE_OPTIONAL_HEADER32 opt{};
        ReadRemote(process, optHdrAddr, &opt, sizeof(opt));
        expDirRva  = opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
        expDirSize = opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].Size;
    } else {
        throw std::runtime_error("Unknown optional-header magic");
    }

    if (expDirRva == 0 || expDirSize == 0)
        return exports; // no exports

    // Read export directory
    IMAGE_EXPORT_DIRECTORY expDir{};
    ReadRemote(process, base + expDirRva, &expDir, sizeof(expDir));

    const DWORD numNames     = expDir.NumberOfNames;
    const DWORD numFunctions = expDir.NumberOfFunctions;
    if (numNames == 0 || numFunctions == 0)
        return exports;

    // Read address-of-functions table
    std::vector<DWORD> funcRvas(numFunctions);
    ReadRemote(process,
               base + expDir.AddressOfFunctions,
               funcRvas.data(),
               numFunctions * sizeof(DWORD));

    // Read name RVA table
    std::vector<DWORD> nameRvas(numNames);
    ReadRemote(process,
               base + expDir.AddressOfNames,
               nameRvas.data(),
               numNames * sizeof(DWORD));

    // Read name-ordinal table
    std::vector<WORD> nameOrdinals(numNames);
    ReadRemote(process,
               base + expDir.AddressOfNameOrdinals,
               nameOrdinals.data(),
               numNames * sizeof(WORD));

    // Build map: name -> RVA
    for (DWORD i = 0; i < numNames; ++i) {
        // Read the null-terminated export name (max 256 chars)
        char nameBuf[256]{};
        std::uintptr_t nameAddr = base + nameRvas[i];
        // Read byte-by-byte up to 255 chars to avoid a large cross-page read
        for (int c = 0; c < 255; ++c) {
            BYTE ch = 0;
            ReadRemote(process, nameAddr + static_cast<std::uintptr_t>(c), &ch, 1);
            if (ch == 0) break;
            nameBuf[c] = static_cast<char>(ch);
        }

        WORD ord = nameOrdinals[i]; // zero-based ordinal bias already removed
        if (ord >= numFunctions)
            continue;

        DWORD funcRva = funcRvas[ord];
        // Skip forwarder entries (RVA inside the export directory)
        if (funcRva >= expDirRva && funcRva < expDirRva + expDirSize)
            continue;

        exports.emplace(nameBuf, funcRva);
    }

    return exports;
}

// ---------------------------------------------------------------------------
// ResolveSymbols
// Given a process handle, a module name, and a list of symbol names, fills
// each SymbolOffset::offset with the RVA from the module base.
// Returns false (and leaves unresolved entries at offset==0) if any symbol
// was not found; returns true when all symbols resolved.
// ---------------------------------------------------------------------------
bool ResolveSymbols(HANDLE           process,
                    DWORD            pid,
                    std::string_view moduleName,
                    std::vector<SymbolOffset>& symbols)
{
    std::uintptr_t base = FindModuleBase(pid, moduleName);
    if (base == 0)
        throw std::runtime_error(
            std::string("Module not found: ") + std::string(moduleName));

    auto exports = ParseExportTable(process, base);

    bool allFound = true;
    for (auto& sym : symbols) {
        auto it = exports.find(sym.name);
        if (it != exports.end()) {
            sym.offset = it->second;
        } else {
            sym.offset = 0;
            allFound   = false;
        }
    }
    return allFound;
}

// ---------------------------------------------------------------------------
// Smoke test — compile with /DSMOKE_TEST to link standalone
// ---------------------------------------------------------------------------
#ifdef SMOKE_TEST
#include <cstdio>

int main()
{
    // Target: ourselves (current process, ntdll.dll)
    DWORD pid = GetCurrentProcessId();
    HANDLE process = OpenProcess(
        PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!process) {
        fprintf(stderr, "OpenProcess failed: %lu\n", GetLastError());
        return 1;
    }

    std::vector<SymbolOffset> syms = {
        { "NtQuerySystemInformation", 0 },
        { "RtlAllocateHeap",          0 },
        { "LdrLoadDll",               0 },
        { "DoesNotExist_XYZ",         0 }, // expected miss
    };

    bool ok = false;
    try {
        ok = ResolveSymbols(process, pid, "ntdll.dll", syms);
    } catch (const std::exception& ex) {
        fprintf(stderr, "Error: %s\n", ex.what());
        CloseHandle(process);
        return 1;
    }

    printf("All resolved: %s\n", ok ? "yes" : "no");
    for (const auto& s : syms) {
        if (s.offset)
            printf("  %-40s  RVA 0x%08X\n", s.name.c_str(), s.offset);
        else
            printf("  %-40s  NOT FOUND\n", s.name.c_str());
    }

    CloseHandle(process);
    return 0;
}
#endif // SMOKE_TEST
